/// <summary>
///    The <c>ISDAppIntgCopyDataToTargetController</c> class initiates async batch jobs to copy staging data to target table with reference to DMF import execution id.
/// </summary>
public class ISDAppIntgCopyDataToTargetController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Initiate an instance of <c>ISDAppIntgCopyDataToTargetController</c> class
/// </summary>
/// <param name = "_className">ISDAppIntgCopyDataToTargetService</param>
/// <param name = "_methodName">MethodName</param>
/// <param name = "_executionMode">SysOperationExecutionMode</param>
protected void new(
    IdentifierName _className = classStr(ISDAppIntgCopyDataToTargetService),
    IdentifierName _methodName = methodStr(ISDAppIntgCopyDataToTargetService, startOperation),
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

/// <summary>
/// Initiate an instance of <c>ISDAppIntgCopyDataToTargetController</c> class from arguments
/// </summary>
/// <param name = "_startOperation">Boolean indicating whether to start the operation; optional.</param>
/// <returns>ISDAppIntgCopyDataToTargetController</returns>
internal static ISDAppIntgCopyDataToTargetController newFromArgs(boolean _startOperation = true)
{
    identifierName className;
    identifierName methodName;
    SysOperationExecutionMode executionMode;

    if (_startOperation)
    {
        className = classStr(ISDAppIntgCopyDataToTargetService);
        methodName = methodStr(ISDAppIntgCopyDataToTargetService, startOperation);
        executionMode = SysOperationExecutionMode::Synchronous;
    }
    else
    {
        className = classStr(ISDAppIntgCopyDataToTargetService);
        methodName = methodStr(ISDAppIntgCopyDataToTargetService, generate);
        executionMode = SysOperationExecutionMode::Synchronous;
    }

    ISDAppIntgCopyDataToTargetController controller = new ISDAppIntgCopyDataToTargetController(className, methodName, executionMode);

    controller.parmLoadFromSysLastValue(false);
    controller.parmDisplayQueryFilter(true);

    return controller;
}

/// <summary>
/// Initiate an instance of <c>ISDAppIntgCopyDataToTargetContract</c> class
/// </summary>
/// <param name="_args">Caller args.</param>
private void initContract(Args _args)
{
    DictMethod dictMethod = new SysDictMethod(UtilElementType::ClassInstanceMethod, className2Id(this.parmClassName()), this.parmMethodName());
    str dataContractKey = dictMethod.parameterName(1);

    ISDAppIntgCopyDataToTargetContract contract = this.getDataContractObject(dataContractKey) as ISDAppIntgCopyDataToTargetContract;

    if (!contract)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
    Common callerRecord = _args.record();

    if (callerRecord.TableId == tableNum(DMFDefinitionGroupExecution))
    {
        if (FormDataUtil::isFormDataSource(callerRecord))
        {
            contract.parmFormDataSource(FormDataUtil::getFormDataSource(callerRecord));
        }

        contract.initQuery();
    }
}

/// <summary>
/// Construct method
/// </summary>
/// <returns>ISDRetStorePlanController</returns>
public static ISDAppIntgCopyDataToTargetController construct()
{
    return new ISDAppIntgCopyDataToTargetController(  classStr(ISDAppIntgCopyDataToTargetService),
                                                        methodStr(ISDAppIntgCopyDataToTargetService, startOperation),
                                                        SysOperationExecutionMode::Synchronous);
}

// AOSRunMode::RunOn
public static void main(Args args)
{
    ISDAppIntgCopyDataToTargetController controller = ISDAppIntgCopyDataToTargetController::newFromArgs(true);

    controller.initContract(args);
    controller.startOperation();
}

